/**
 * Shared generation and delivery for every emailed one-time code.
 *
 * Extracted so the OTP, email-verification and password-reset providers cannot
 * drift apart on the two things that matter: how the code is generated, and
 * whether it ever reaches a log.
 */

const DIGITS = 8;

/**
 * 8 cryptographically random digits, generated by REJECTION SAMPLING.
 *
 * The previous implementation did `bytes[i] % 10`. With 256 byte values that is
 * biased: 0-5 each arise from 26 byte values, 6-9 from only 25. The bias is
 * small but free to remove, and biased "random" in an auth primitive is the kind
 * of thing that is embarrassing to explain later. Values >= 250 are discarded so
 * the remaining range is an exact multiple of 10.
 */
export function generateNumericCode(length = DIGITS): string {
  let out = "";
  const buf = new Uint8Array(length * 2);
  while (out.length < length) {
    crypto.getRandomValues(buf);
    for (const b of buf) {
      if (b >= 250) continue;
      out += (b % 10).toString();
      if (out.length === length) break;
    }
  }
  return out;
}

/**
 * True when the deployment has a real mail transport configured.
 *
 * Gates the dev fallback below. Codes are only ever logged when there is no
 * other way for a developer to receive them.
 */
export function hasMailTransport(): boolean {
  return Boolean(process.env.SMTP_HOST || process.env.RESEND_API_KEY);
}

import { internal } from "./_generated/api";

type Ctx = {
  runAction: (ref: unknown, args: unknown) => Promise<unknown>;
  runMutation?: (ref: unknown, args: unknown) => Promise<unknown>;
};

/**
 * Email a code, and log it ONLY when no transport exists.
 *
 * This closes a real production leak. Previously every OTP, verification and
 * reset code was written to the Convex log stream unconditionally, so anyone who
 * could read deployment logs could authenticate as any user — a full
 * authentication bypass that leaves no trace in the auth events. The codes were
 * genuinely harvestable from the live deployment.
 *
 * The fallback survives only for local development, where SMTP_HOST and
 * RESEND_API_KEY are both unset and there is no inbox to read.
 */
export async function deliverCode(
  ctx: Ctx | undefined,
  label: string,
  email: string,
  token: string,
  sendEmail: unknown,
): Promise<void> {
  // Per-email send throttle (cooldown + hourly cap). SKIP silently when over
  // the limit — never throw, so requestPasswordReset and the library's signIn
  // keep their constant "started" response. All three code providers (verify /
  // reset / otp) reach here, so this one gate covers every emailed code.
  if (ctx && typeof ctx.runMutation === "function") {
    const allowed = await ctx.runMutation(internal.authProbe.recordSend, {
      email,
    });
    if (allowed === false) return;
  }
  if (!hasMailTransport()) {
    console.warn(`[auth] ${label} code for ${email}: ${token}`);
  }
  try {
    await ctx?.runAction(sendEmail, {
      to: email,
      subject: `Your ${label} code`,
      text: `Your ${label} code is ${token}`,
    });
  } catch (e) {
    // Never include the token in an error path.
    console.warn(`[email] ${label} send failed: ${(e as Error).message}`);
  }
}
